-- ============================================================
--  FlipujKáru — naplnění „Ukázek úspěšných flipů" do tabulky cars
--  Vygenerováno z FLIPS v src/data/content.js (fotky v public/flips,
--  originály v data/ukazky_flipu). Každý flip = auto se status 'sold'.
--  Bezpečné pustit opakovaně: vkládá jen flipy, které v DB ještě nejsou
--  (shoda značka + model + prodejní cena mezi prodanými auty). Výjimka: BMW X6
--  už v DB existuje jako prodané auto bez příběhu → doplní se mu údaje.
-- ============================================================

insert into public.cars (brand, model, year, price, category, status, sort, image_url, images, badge_text, badge_tone, buy_price, repair_cost, sell_price, flip_weeks, location, found_note, problems, work, story)
select 'BMW', '530d xDrive Touring M', 2018, 509000, 'denni', 'sold', 0, '/flips/bmw-530d-touring.jpg', '["/flips/bmw-530d-touring.jpg"]'::jsonb, 'PRODÁNO', 'sold', 429000, 9000, 509000, 4, 'Mnichov, Německo', 'Algoritmus zachytil dovozový inzerát v Německu — cena seděla i přes vyšší nájezd díky M-Paketu a bohaté výbavě.', '["Lakovaný levý zadní blatník po drobné nehodě (transparentně uvedeno v inzerátu)","Vyšší nájezd 157 800 km"]'::jsonb, '["Transparentní popis opravy přímo v inzerátu vč. fotky","Standardní příprava k prodeji"]'::jsonb, 'M-Paket a kompletní výbava táhly zájem navzdory vyššímu nájezdu. Kupci vadil málokdy — spíš se ptali na důvod laku, dostali upřímnou odpověď a auto si odvezli do týdne od prohlídky.'
where not exists (select 1 from public.cars where status = 'sold' and brand = 'BMW' and model = '530d xDrive Touring M' and sell_price = 509000);

insert into public.cars (brand, model, year, price, category, status, sort, image_url, images, badge_text, badge_tone, buy_price, repair_cost, sell_price, flip_weeks, location, found_note, problems, work, story)
select 'Audi', 'SQ5 3.0 TFSI 260 kW', 2018, 729000, 'denni', 'sold', 1, '/flips/audi-sq5.jpg', '["/flips/audi-sq5.jpg"]'::jsonb, 'PRODÁNO', 'sold', 619800, 19000, 729000, 9, 'Praha, Česko', 'Vůz z aukce, kde díky málo poptávanému provedení šla cena hluboko pod tržní úroveň — jedinečnost na trhu ale znamenala i delší prodej.', '["Poškozený lak na levém předním blatníku (stříkance)","Zanedbaný interiér","Potřeba výměny oleje"]'::jsonb, '["Kompletní přeleštění celého vozu","Ozonové čištění a hloubkové čištění interiéru","Výměna oleje","Oprava a přelakování předního blatníku"]'::jsonb, 'Skvělá nákupní cena, ale s autem bylo víc práce než obvykle. Po důkladné přípravě se přesto prodalo se ziskem přes 90 000 Kč — jen to trvalo o něco déle, protože SQ5 v této konfiguraci nemá na trhu moc srovnání.'
where not exists (select 1 from public.cars where status = 'sold' and brand = 'Audi' and model = 'SQ5 3.0 TFSI 260 kW' and sell_price = 729000);

insert into public.cars (brand, model, year, price, category, status, sort, image_url, images, badge_text, badge_tone, buy_price, repair_cost, sell_price, flip_weeks, location, found_note, problems, work, story)
select 'Volkswagen', 'Arteon R-Line 2.0 TDI 110 kW', 2021, 567000, 'denni', 'sold', 2, '/flips/arteon-rline-110kw.jpg', '["/flips/arteon-rline-110kw.jpg"]'::jsonb, 'PRODÁNO', 'sold', 519000, 4000, 567000, 4, 'Praha, Česko', 'Vůz z aukce, který jsme sledovali kvůli konkrétní motorizaci a výbavě R-Line.', '["Segment, kde kupci automaticky srovnávají s konkurencí"]'::jsonb, '["Standardní příprava a detailing","Drobné doladění před inzercí"]'::jsonb, 'Auto se nakonec prodalo se ziskem, ale trvalo to déle — lidi v tomhle segmentu systematicky srovnávají Arteon se Superbem Combi a dávají mu přednost, ne kvůli karoserii, ale kvůli značce a servisní dostupnosti.'
where not exists (select 1 from public.cars where status = 'sold' and brand = 'Volkswagen' and model = 'Arteon R-Line 2.0 TDI 110 kW' and sell_price = 567000);

insert into public.cars (brand, model, year, price, category, status, sort, image_url, images, badge_text, badge_tone, buy_price, repair_cost, sell_price, flip_weeks, location, found_note, problems, work, story)
select 'Volkswagen', 'Arteon R-Line 2.0 TDI 110 kW', 2023, 699800, 'denni', 'sold', 3, '/flips/arteon-rline-blue-own.jpg', '["/flips/arteon-rline-blue-own.jpg"]'::jsonb, 'PRODÁNO', 'sold', 629300, 0, 699800, 3, 'Brno, Česko', 'Vůz z vlastní sítě kontaktů, bez zveřejněné inzerce.', '["Žádné — auto bylo v top stavu"]'::jsonb, '["Jen standardní příprava a focení, žádné opravy"]'::jsonb, 'Modrá barva byla první, co lidi na inzerátu zaujala — na trhu jsou skoro všechny R-line kusy černé nebo šedé, takže tenhle vyčníval. Navíc měl výbavu nad rámec běžného balíčku. První prohlídka skončila rezervací.'
