insert into public.cars (brand, model, year, price, category, status, sort, image_url, images, badge_text, badge_tone, buy_price, repair_cost, sell_price, flip_weeks, location, found_note, problems, work, story)
select 'Volkswagen', 'Arteon R-Line 4MOTION', 2023, 749000, 'denni', 'sold', 4, '/flips/arteon-rline-4motion-aukce.jpg', '["/flips/arteon-rline-4motion-aukce.jpg"]'::jsonb, 'PRODÁNO', 'sold', 649000, 20000, 749000, 3, 'Drážďany, Německo', 'Vůz z aukce, který k nám přijel přímo z Německa.', '["Nutnost přehlášení a STK po dovozu","Drobné kosmetické nedostatky interiéru i exteriéru"]'::jsonb, '["Přehlášení a STK","Drobný detailing interiéru a exteriéru","Kompletní servis"]'::jsonb, 'První týden šel na papíry, inzerát jsme vystavili až druhý týden — ale hned se ozvali tři zájemci. Nejvážnější dojel z Ostravy, na testovačce ho dostala Alcantara a DCC podvozek. Auto odjelo 21. den s plnou nádrží jako bonus.'
