insert into public.cars (brand, model, year, price, category, status, sort, image_url, images, badge_text, badge_tone, buy_price, repair_cost, sell_price, flip_weeks, location, found_note, problems, work, story)
select 'BMW', '520d xDrive M-paket', 2025, 1599000, 'denni', 'sold', 8, '/flips/bmw-520-xdrive.jpg', '["/flips/bmw-520-xdrive.jpg"]'::jsonb, 'PRODÁNO', 'sold', 1349000, 54000, 1599000, 8, 'Mnichov, Německo', 'Algoritmus zachytil téměř nový vůz v záruce — bílý interiér, 4zónová klimatizace a Head-Up display za výbornou cenu.', '["Základní vzhled bez odlišení od běžného 520 v základu"]'::jsonb, '["Vlastní úprava vzhledu — Maxton lipa přední/zadní spoiler","Dechrom","Přestříkání kol na černo"]'::jsonb, 'Auto jsme si vzali a upravili podle vlastního vkusu. Vypadalo úplně jinak než typický 520 v základu — zájemci si toho hned všimli a byli ochotní si za ten look připlatit. Nakonec jsme dosáhli výrazně vyššího zisku, než jsme čekali.'
