update public.cars set buy_price = 1680690, repair_cost = 0, sell_price = 1799999, flip_weeks = 3, location = 'Miláno, Itálie', found_note = 'Algoritmus zachytil dovozový inzerát v Itálii — luxusní SUV s výbavou a zárukou hluboko pod tržní cenou.', problems = '["Italský původ, který u kupců budí přirozenou opatrnost"]'::jsonb, work = '["Důkladné prověření historie a právního stavu","Standardní příprava k prodeji"]'::jsonb, story = 'Italský původ jsme prověřili do detailu — bez problémů a se zárukou. Prodej šel rychleji, než jsme čekali.', sort = 9
